package com.acme.workers

import java.util.Properties
import javax.mail.*
import javax.mail.internet.*

// Feature flag service - checks remote config
object FeatureFlags {
    private val flags = mutableMapOf<String, Boolean>()

    fun init(config: Map<String, Boolean>) {
        flags.putAll(config)
    }

    fun isEnabled(flag: String): Boolean = flags.getOrDefault(flag, false)
}

// Domain model
data class NotificationJob(
    val jobId: String,
    val recipientEmail: String,
    val recipientName: String,
    val subject: String,
    val templateId: String,
    val metadata: Map<String, String>
)

// Email sanitization utilities
object EmailSanitizer {
    private val CRLF_PATTERN = Regex("[\\r\\n]")
    private val HEADER_INJECTION_PATTERN = Regex("[\\r\\n]+(Bcc|Cc|To|Subject|Content-Type):")

    fun sanitizeHeaderValue(value: String): String {
        return value.replace(CRLF_PATTERN, "")
    }

    fun sanitizeEmailAddress(email: String): String {
        return email.replace(CRLF_PATTERN, "").trim()
    }

    fun isValidEmail(email: String): Boolean {
        return email.matches(Regex("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))
    }

    fun containsInjection(value: String): Boolean {
        return HEADER_INJECTION_PATTERN.containsMatchIn(value)
    }
}

// Encoding strategy interface for recipient formatting
interface RecipientEncoder {
    fun encode(email: String, displayName: String): String
}

// RFC 2047 encoded-word format for display names with special chars
class Rfc2047Encoder : RecipientEncoder {
    override fun encode(email: String, displayName: String): String {
        val sanitizedEmail = EmailSanitizer.sanitizeEmailAddress(email)
        val sanitizedName = EmailSanitizer.sanitizeHeaderValue(displayName)
        if (sanitizedName.isBlank()) return sanitizedEmail
        // Use RFC 2047 encoding for the display name
        val encoded = "=?UTF-8?B?${java.util.Base64.getEncoder().encodeToString(sanitizedName.toByteArray())}?="
        return "$encoded <$sanitizedEmail>"
    }
}

// Simple format: "Name <email>"
class SimpleRecipientEncoder : RecipientEncoder {
    override fun encode(email: String, displayName: String): String {
        val sanitizedEmail = EmailSanitizer.sanitizeEmailAddress(email)
        // Sanitize display name to prevent header injection
        val sanitizedName = EmailSanitizer.sanitizeHeaderValue(displayName)
        if (sanitizedName.isBlank()) return sanitizedEmail
        return "$sanitizedName <$sanitizedEmail>"
    }
}

// Factory that selects encoder based on feature flags
object RecipientEncoderFactory {
    fun create(): RecipientEncoder {
        return if (FeatureFlags.isEnabled("use_rfc2047_encoding")) {
            Rfc2047Encoder()
        } else {
            SimpleRecipientEncoder()
        }
    }
}

// The background job worker
class NotificationWorker(
    private val smtpHost: String = "smtp.internal.acme.com",
    private val smtpPort: Int = 587,
    private val fromAddress: String = "noreply@acme.com"
) {
    private val session: Session by lazy {
        val props = Properties().apply {
            put("mail.smtp.host", smtpHost)
            put("mail.smtp.port", smtpPort.toString())
            put("mail.smtp.auth", "true")
        }
        Session.getInstance(props)
    }

    fun processJob(job: NotificationJob): Result<Unit> {
        return try {
            // Validate email
            if (!EmailSanitizer.isValidEmail(job.recipientEmail)) {
                return Result.failure(IllegalArgumentException("Invalid email: ${job.recipientEmail}"))
            }

            // Check for obvious injection in subject
            val safeSubject = EmailSanitizer.sanitizeHeaderValue(job.subject)

            // Build recipient using the configured encoder
            val encoder = RecipientEncoderFactory.create()
            val formattedRecipient = encoder.encode(job.recipientEmail, job.recipientName)

            // Construct message
            val message = MimeMessage(session).apply {
                setFrom(InternetAddress(fromAddress))
                setRecipients(
                    Message.RecipientType.TO,
                    InternetAddress.parse(formattedRecipient)
                )
                subject = safeSubject

                // Add custom headers from metadata if feature enabled
                if (FeatureFlags.isEnabled("custom_tracking_headers")) {
                    job.metadata.forEach { (key, value) ->
                        val headerName = "X-Acme-${EmailSanitizer.sanitizeHeaderValue(key)}"
                        val headerValue = EmailSanitizer.sanitizeHeaderValue(value)
                        addHeader(headerName, headerValue)
                    }
                }

                setText(buildEmailBody(job), "UTF-8", "html")
            }

            Transport.send(message)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    private fun buildEmailBody(job: NotificationJob): String {
        return "<html><body><p>Hello ${EmailSanitizer.sanitizeHeaderValue(job.recipientName)}</p></body></html>"
    }
}

// Entry point for the worker process
fun main() {
    // Feature flags loaded from remote config service
    FeatureFlags.init(mapOf(
        "use_rfc2047_encoding" to false,
        "custom_tracking_headers" to true
    ))

    val worker = NotificationWorker()

    // Simulate processing a job from the queue
    val job = NotificationJob(
        jobId = "job-12345",
        recipientEmail = "user@example.com",
        recipientName = "John Doe",
        subject = "Your order is ready",
        templateId = "order_ready",
        metadata = mapOf("campaign" to "summer2024", "jobId" to "job-12345")
    )

    worker.processJob(job)
}
